			}
		})
		.done(function(){
    		var actionId = "ASIPRB002MR06";
    		var params = {};
    		var userDcmRgtAth = [];

    		Req.doAction(actionId,params)
    		.done(function(data){
    			if(data[actionId]){
    				if(data[actionId]["dcmRgtAthList"]){
    					userDcmRgtAth = data[actionId]["dcmRgtAthList"];
    					userDcmRgtAth.sort();

    		   			if(userDcmRgtAth.length > 0 && Biz.aprvYn != "Y"){
   		   					Biz.pmsDcmCdList = userDcmRgtAth;
    		   			}
    				}    				
    			}
    		})
			.done(function(){
    			if(!Biz.pmsDcmCdList.length > 0 && Biz.aprvYn != "Y"){
    				Page.alert("접근 권한이 없습니다.",function(){
						if(Biz.paramsData["ntstDcmGrpCd"] == "01"){
