    			console.log(error.message);
    			if(Biz.paramsData["ntstDcmGrpCd"] == "01"){
					Page.move("USIPRB001M.do?ntstDcmGrpCd="+Biz.paramsData["ntstDcmGrpCd"]);
				}else if(Biz.paramsData["ntstDcmGrpCd"] == "02"){
					Page.move("USIPRC018M.do?ntstDcmGrpCd="+Biz.paramsData["ntstDcmGrpCd"]);
				}	
			})
		})
		.fail(function(error) {	// 오류시 처리해야 할 프로세스가 있을 경우 작성
    		console.log(error.message);
    		if(Biz.paramsData["ntstDcmGrpCd"] == "01"){
				Page.move("USIPRB001M.do?ntstDcmGrpCd="+Biz.paramsData["ntstDcmGrpCd"]);
			}else if(Biz.paramsData["ntstDcmGrpCd"] == "02"){
