(function(win){
	var _table = function($objId){
		$objId.attr("data-component-type", "table");
		if($objId.attr('id')){ 
			this._id = $objId.attr('id');
		}else{
			var InstantId = "TABLEID" + new Date().getTime() + "_" + $(document).find('[data-component-type="table"]').length;
			$objId.attr('id', InstantId);
			this._id = InstantId;
		}
		this._cnt = 0;

		this._colIdx = new Object(); // { yearlyChange : 1, ...}
		this._headerList = new Array();	// 헤더정보 저장

		this._dataOpt = null;

		this.setData = function(data, opt){
			$("#" + this._id+" tbody tr").remove();
			this.addData(data, opt);

		};
		this.addData = function(data, opt){
			var trList = null;
			if(data.length>0){
				this._dataOpt = $.extend({}, {
					cellTemplate : {}
					,tdClassFunc : {}
				}, opt); 
				this._setColIdx();
				trList = this._makeHtml(data);
				//초기화
			}else{
				this._setColIdx();
				trList = $('<tr>').append($('<td>').attr('colspan',this._cnt).append($('<span>').addClass('no_data').text('검색 결과가 없습니다.')));
			}
			$("#" + this._id).find("tbody").append(trList);
		};

		this.onRowClick = function(func){
			if (typeof func != 'function') return;

			var trList = $("#" + this._id + " tbody").find("tr");

			//이전 이벤트 클리어
			trList.each(function(){
				$(this).off("click");
			});
			trList.each(function(){
				$(this).css("cursor", "pointer");
				$(this).click(function(){
					var rowData = $(this).data("rowData");
					func(rowData);
				});
			});	
		};

		this.onCellClick = function(colId, func){
			if (typeof func != 'function') return;

			var tdList = $("#" + this._id + " tbody").find("td[data-cell-id="+ colId +"]");
			//이전 이벤트 클리어
			tdList.each(function(){
				$(this).off("click");
			});
			tdList.each(function(){
				$(this).css("cursor", "pointer");
				$(this).click(function(){
					var rowData = $(this).parent().data("rowData");
					var colData = $(this).data("colData");
					func(rowData, colData);
				});
			});
		};

		this._setColIdx = function() {
			var tmpColIdx = {};
			var colCnt = 0;
			$('#' + this._id + ' colgroup [data-column-id]').each(function(i) {
				colCnt++;
				var dataId = $(this).data("column-id");
				var tmpObj = {};
				tmpObj[dataId] = i;
				Object.assign(tmpColIdx, tmpObj);
			});
			this._cnt = colCnt;
			this._colIdx = tmpColIdx;
		};

		/* deprecated */
		this._setHeaderList = function(){	// table내 헤더정보를 읽어 객체에 저장한다.
			var rtnHeaderList = [];
			$('#' + this._id + ' colgroup [data-column-id]').each(function(i) {
				var dataId = $(this).data("column-id");
				rtnHeaderList.push({"columnId": dataId});
			});

			this._headerList = rtnHeaderList;
		}

		/*
		헤더정보를 반환한다.
		 */
		this._getHeader = function(colKey){
			var header = null;
			$("#" + this._id).find("colgroup col").each(function(){
				if(colKey == $(this).attr("data-column-id")){
					header = $(this);
					return false;
				}
			});

			if(null == header){
				return null;
			}

			return {
				"id": header.attr("data-column-id")
				,"align" : header.attr("data-column-align")
			};
		}

		this._makeHtml = function(jsonData){
			var $this = this;

			var trLen = jsonData.length;
			var tdData = Object.keys(this._colIdx);
			var tdLen = tdData.length;
			var rtnArr = new Array();

			var _dataOpt = this._dataOpt;


			for (var i = 0; i < trLen; ++i) {
				var data = jsonData[i]; //yC : xx, c : x
				if (data == null) continue;
				var tr = $("<tr>").data("rowData", data);

				for (var j = 0; j < tdLen; ++j) {
					var td = null;
					if(data[tdData[j]] === 'undefined'){
						td = $("<td>").text("").data("colData", null);
					}else{
						var templateFunc = _dataOpt.cellTemplate[tdData[j]];	//업무에서 지정한 cell에 대한 템플릿 함수
						var tdClassFunc = _dataOpt.tdClassFunc[tdData[j]];	//업무에서 지정한 cell에 대한 템플릿 함수
						var rowData = data;
						var cellData = Util.replaceDateFormatForDoc(data[tdData[j]]);

						if(typeof templateFunc == 'function'){
							td = $("<td>").append(templateFunc(cellData, rowData)).data("colData", cellData);

						}else{
							td = $("<td>").text(data[tdData[j]]).data("colData", cellData);
						}

						if(typeof tdClassFunc == 'function'){
							td.addClass(tdClassFunc(cellData, rowData));									
						}

						var headerInfo = $this._getHeader(tdData[j]);
						if("left" == headerInfo.align){
							td.addClass("text_l");
						}
					}

					td.attr("data-cell-id", tdData[j]);
					tr.append(td);
				}
				rtnArr.push(tr);

			}
			return rtnArr;
		};

	};

	win.Table = _table;

	//달력
